# verify rule on demo with threshold t: fill 4s strictly between consecutive 9s in a row/col if gap<=t
def solve(g,t):
    R,C=len(g),len(g[0]); o=[row[:] for row in g]
    for r in range(R):
        nines=[c for c in range(C) if g[r][c]==9]
        for a,b in zip(nines,nines[1:]):
            if b-a-1<=t:
                for c in range(a+1,b): 
                    if o[r][c]==4: o[r][c]=2
    for c in range(C):
        nines=[r for r in range(R) if g[r][c]==9]
        for a,b in zip(nines,nines[1:]):
            if b-a-1<=t:
                for r in range(a+1,b):
                    if o[r][c]==4: o[r][c]=2
    return o
